  border-radius: 9px; background: rgba(7, 12, 16, 0.68); border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(10px); min-width: 68px;
}
.hud-chip span { color: #697781; font-size: 7px; font-weight: 800; letter-spacing: 0.16em; }
.hud-chip strong { color: #dfe8ed; font-family: var(--mono); font-size: 11px; font-weight: 600; }
.hud-chip.hud-reactions strong { color: var(--accent-2); }
.sim-controls { position: absolute; top: 14px; right: 14px; z-index: 7; display: flex; gap: 5px; padding: 4px; border-radius: 11px; background: rgba(7, 12, 16, 0.72); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(10px); }
.sim-btn {
  width: 30px; height: 28px; border: 0; border-radius: 7px; background: transparent; color: #84919a;
