.sim-btn .icon-play { display: none; }
.sim-btn.paused .icon-pause { display: none; }
.sim-btn.paused .icon-play { display: block; color: var(--lime); }
.scene-badge {
  position: absolute; right: 16px; bottom: 112px; z-index: 5; display: flex; flex-direction: column; align-items: flex-end; gap: 3px;
