.scene-badge span { color: #66747e; font-size: 7px; font-weight: 800; letter-spacing: 0.2em; }
.scene-badge strong { font-size: 10px; font-weight: 700; color: #c9d3d9; }
.hud-bottom {
  left: 14px; right: 14px; bottom: 14px; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px;
}
.tool-dock {
  display: flex; align-items: center; gap: 3px; padding: 5px; border-radius: 12px;
  background: rgba(7, 12, 16, 0.78); border: 1px solid rgba(255, 255, 255, 0.09);
