}
.tool-dock::-webkit-scrollbar { display: none; }
.tool {
  position: relative; width: 48px; height: 46px; border: 0; border-radius: 8px; background: transparent;
  color: #7e8a93; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  cursor: pointer; transition: all 140ms ease; flex: 0 0 auto;
}
.tool svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.tool span { font-size: 7.5px; font-weight: 650; letter-spacing: 0.02em; }
.tool:hover { color: #e4ebef; background: rgba(255, 255, 255, 0.06); }
