.brush-control {
  display: flex; align-items: center; gap: 9px; padding: 8px 10px; border-radius: 10px;
  background: rgba(7, 12, 16, 0.72); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(10px); pointer-events: auto;
}
.brush-control span { color: #67747e; font-size: 7px; font-weight: 800; letter-spacing: 0.14em; }
.brush-control input { width: 76px; accent-color: var(--accent); height: 14px; }
.brush-control output { font-family: var(--mono); font-size: 10px; color: var(--text); min-width: 14px; text-align: right; }
.mobile-dock-hint { display: none; }

.inspector { display: flex; flex-direction: column; overflow-y: auto; scrollbar-width: thin; scrollbar-color: #28323b transparent; }
.inspector::-webkit-scrollbar { width: 6px; }
.inspector::-webkit-scrollbar-thumb { background: #26313a; border-radius: 99px; }
.selected-card { display: flex; gap: 12px; align-items: center; padding: 0 16px 14px; }
