  padding: 8px 9px; border-radius: 9px; background: rgba(255, 255, 255, 0.028); border: 1px solid rgba(255, 255, 255, 0.055);
}
.prop-label { display: flex; align-items: center; justify-content: space-between; gap: 4px; color: #6f7c85; font-size: 7.5px; font-weight: 750; letter-spacing: 0.07em; text-transform: uppercase; }
.prop-value { color: #e3eaee; font-family: var(--mono); font-size: 10px; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
