.section-title { margin: 14px 16px 7px; color: #6b7881; font-size: 7.5px; font-weight: 850; letter-spacing: 0.18em; text-transform: uppercase; }
.behavior { margin: 0 16px; color: #a9b4bc; font-size: 10px; line-height: 1.55; }
.thermal-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; padding: 0 14px; }
.thermal { padding: 7px 8px; border-radius: 8px; background: rgba(255, 255, 255, 0.022); border: 1px solid rgba(255, 255, 255, 0.05); }
.thermal span { display: block; color: #6c7982; font-size: 7px; font-weight: 750; letter-spacing: 0.07em; text-transform: uppercase; }
