.inspector-foot { margin-top: auto; display: flex; align-items: center; gap: 7px; padding: 10px 14px; border-top: 1px solid var(--line); color: #5f6b75; font-size: 8px; }
.inspector-foot .lazy-dot { background: var(--accent); box-shadow: 0 0 8px rgba(255, 157, 60, 0.6); }

.scene-menu {
  position: fixed; top: 62px; right: 76px; width: 268px; z-index: 60;
