  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55); padding: 7px;
  opacity: 0; transform: translateY(-6px) scale(0.98); pointer-events: none;
  transition: opacity 150ms ease, transform 150ms ease;
}
.scene-menu.open { opacity: 1; transform: none; pointer-events: auto; }
.scene-menu-head { padding: 8px 10px 9px; border-bottom: 1px solid var(--line); margin-bottom: 5px; }
.scene-menu-head span { display: block; color: var(--accent); font-size: 7px; font-weight: 850; letter-spacing: 0.18em; }
.scene-menu-head strong { display: block; margin-top: 4px; font-size: 11px; font-weight: 650; }
.scene-option { width: 100%; display: flex; align-items: center; gap: 10px; border: 0; background: transparent; padding: 7px 9px; border-radius: 8px; cursor: pointer; text-align: left; }
.scene-option:hover { background: rgba(255, 255, 255, 0.055); }
.scene-option.active { background: rgba(255, 157, 60, 0.1); }
.scene-option b { display: block; font-size: 10.5px; font-weight: 650; }
.scene-option small { display: block; margin-top: 2px; color: #697781; font-size: 8px; }
.scene-icon { width: 28px; height: 28px; border-radius: 7px; flex: 0 0 auto; border: 1px solid rgba(255, 255, 255, 0.1); }
.scene-icon.volcano { background: radial-gradient(circle at 50% 80%, #ff6a1d 0 18%, transparent 20%), linear-gradient(145deg, #232b30, #0e1418); }
.scene-icon.garden { background: radial-gradient(circle at 30% 30%, #b8f26b 0 17%, transparent 19%), linear-gradient(145deg, #203b2a, #0d1711); }
.scene-icon.lab { background: linear-gradient(135deg, #62e7ff 0 20%, transparent 21%), linear-gradient(145deg, #25333d, #0e171d); }
.scene-icon.desert { background: linear-gradient(170deg, #e6bd72 0 45%, #a36b34 46% 100%); }
.scene-icon.space { background: radial-gradient(circle at 68% 32%, #fff 0 4%, transparent 5%), radial-gradient(circle at 35% 62%, #b38cff 0 13%, transparent 14%), linear-gradient(145deg, #1a1430, #07070d); }

.sheet-backdrop {
