  mushroom: '<path d="M4 11a8 8 0 0 1 16 0H4Z"/><path d="M9 11v6a3 3 0 0 0 6 0v-6"/><path d="M7 8c1.4-1.4 3-2 5-2s3.6.6 5 2"/>',
